-- Adds the slot equipment the importer's allow-list missed (importers skill, bug 8): the Dumper on 5 mechs
-- and the Fluid Suction System (Light - Mech) on 2. A dumper takes one slot, so each is its own item (the
-- Lumberjack LM4/C and MuckRaker GMMM-2 have two), rear-facing when written "Dumper (Rear)".
--
-- Generated from a database V3_8 to V3_10 loaded and the fixed importer then re-imported (mechs, then
-- vehicles, mm-data at d195e171b3c87801c8dbc5ffcb5f763e5da57483), by comparing each unit's items before
-- and after: only these 9 were added, nothing changed or went. Units are found by MegaMek uuid, an item is
-- added only if the unit doesn't have it in that place yet, and a slang term only if its lookup is free,
-- so this also runs on a database that was re-imported since.
-- Data migrations after V3_8 update what's stored; see the importers skill.

-- 1. The items
INSERT INTO equipment (id, crit_slots, damage, heat, long_range, medium_range, min_range, name, short_range, tech, tonnage, display_name) SELECT '06decdc8-b6d9-423a-9411-17fe86e84dcf', 0, NULL, 0, 0, 0, 0, 'dumper', 0, 'INNER_SPHERE', 0, 'Dumper' WHERE NOT EXISTS (SELECT 1 FROM equipment WHERE name = 'dumper' AND tech = 'INNER_SPHERE');
INSERT INTO equipment (id, crit_slots, damage, heat, long_range, medium_range, min_range, name, short_range, tech, tonnage, display_name) SELECT '870067b8-48f2-4359-ac8b-e9cc3df597d5', 0, NULL, 0, 0, 0, 0, 'fluidsuctionsystem(light-mech)', 0, 'INNER_SPHERE', 0, 'Fluid Suction System (Light - Mech)' WHERE NOT EXISTS (SELECT 1 FROM equipment WHERE name = 'fluidsuctionsystem(light-mech)' AND tech = 'INNER_SPHERE');
INSERT INTO slang (id, term, lookup, kind) SELECT '257b661c-e7ff-481d-b0d9-823f567efa27', 'Fluid Suction System (Light - Mech)', 'fluidsuctionsystemlightmech', 'ALIAS' WHERE NOT EXISTS (SELECT 1 FROM slang WHERE lookup = 'fluidsuctionsystemlightmech');
INSERT INTO slang (id, term, lookup, kind) SELECT 'aea1328d-832e-4190-aa44-790eac9ee05d', 'Light Fluid Suction System (Mech)', 'lightfluidsuctionsystemmech', 'ALIAS' WHERE NOT EXISTS (SELECT 1 FROM slang WHERE lookup = 'lightfluidsuctionsystemmech');
INSERT INTO slang_equipment (slang_id, equipment_id) SELECT s.id, e.id FROM slang s, equipment e WHERE s.kind = 'ALIAS' AND s.lookup = 'fluidsuctionsystemlightmech' AND s.term = 'Fluid Suction System (Light - Mech)' AND e.name = 'fluidsuctionsystem(light-mech)' AND e.tech = 'INNER_SPHERE' AND NOT EXISTS (SELECT 1 FROM slang_equipment x WHERE x.slang_id = s.id AND x.equipment_id = e.id);
INSERT INTO slang_equipment (slang_id, equipment_id) SELECT s.id, e.id FROM slang s, equipment e WHERE s.kind = 'ALIAS' AND s.lookup = 'lightfluidsuctionsystemmech' AND s.term = 'Light Fluid Suction System (Mech)' AND e.name = 'fluidsuctionsystem(light-mech)' AND e.tech = 'INNER_SPHERE' AND NOT EXISTS (SELECT 1 FROM slang_equipment x WHERE x.slang_id = s.id AND x.equipment_id = e.id);

-- 2. Each unit's new items, added unless the unit has them there already (a database re-imported since)
WITH added AS (INSERT INTO unit_equipment (id, location, omni_pod, rear_facing, tonnage, turret_equipped, equipment_id, fire_control, jump_boost) SELECT gen_random_uuid(), 'LEFT_TORSO', 'f', 'f', 0, 'f', e.id, NULL, NULL FROM unit u, equipment e, generate_series(1, 1) WHERE u.megamek_uuid = '019f583e-ddf4-7691-baaf-ad4e9ba64563' AND e.name = 'dumper' AND e.tech = 'INNER_SPHERE' AND NOT EXISTS (SELECT 1 FROM unit_mech_equipment ume JOIN unit_equipment ue ON ue.id = ume.mech_equipment_id WHERE ume.unit_id = u.id AND ue.equipment_id = e.id AND ue.location IS NOT DISTINCT FROM 'LEFT_TORSO' AND ue.rear_facing = 'f') RETURNING id) INSERT INTO unit_mech_equipment (unit_id, mech_equipment_id) SELECT (SELECT id FROM unit WHERE megamek_uuid = '019f583e-ddf4-7691-baaf-ad4e9ba64563'), id FROM added; -- Grommet D90 MilitiaMech: dumper LEFT_TORSO
WITH added AS (INSERT INTO unit_equipment (id, location, omni_pod, rear_facing, tonnage, turret_equipped, equipment_id, fire_control, jump_boost) SELECT gen_random_uuid(), 'RIGHT_TORSO', 'f', 't', 0, 'f', e.id, NULL, NULL FROM unit u, equipment e, generate_series(1, 1) WHERE u.megamek_uuid = '019f583e-cecc-7c4a-8d07-d6228115e73b' AND e.name = 'dumper' AND e.tech = 'INNER_SPHERE' AND NOT EXISTS (SELECT 1 FROM unit_mech_equipment ume JOIN unit_equipment ue ON ue.id = ume.mech_equipment_id WHERE ume.unit_id = u.id AND ue.equipment_id = e.id AND ue.location IS NOT DISTINCT FROM 'RIGHT_TORSO' AND ue.rear_facing = 't') RETURNING id) INSERT INTO unit_mech_equipment (unit_id, mech_equipment_id) SELECT (SELECT id FROM unit WHERE megamek_uuid = '019f583e-cecc-7c4a-8d07-d6228115e73b'), id FROM added; -- Lumberjack LM1/A: dumper RIGHT_TORSO (rear)
